#!/usr/bin/env python3
"""Module-size lint for authored planning package modules (PRD 082 phase 15 / R27)."""
from __future__ import annotations

import argparse
import json
import sys
from dataclasses import dataclass
from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent
if str(SCRIPT_DIR) not in sys.path:
    sys.path.insert(0, str(SCRIPT_DIR))

from _sw.cli import run_module_main

MODULE_LINE_CAP = 1000
AUTHORED_PACKAGE_PREFIX = "scripts/planning/"
DIST_PREFIXES = ("dist/cursor/", "dist/claude-code/")
VENDOR_PART = "_sw/vendor"
GENERATED_MARKERS = ("GENERATED BY", "planning-store-shim/v1")
COMPAT_REMOVAL_MILESTONE = "zero-inventoried-imports-across-enforced-trees"

SHIM_EXEMPTIONS: tuple[dict[str, str], ...] = (
    {
        "path": "scripts/planning_store.py",
        "reason": "generated-compat-shim",
        "expiresWith": "compat-removal-milestone",
        "milestone": COMPAT_REMOVAL_MILESTONE,
    },
    {
        "path": "core/scripts/planning_store.py",
        "reason": "generated-compat-shim",
        "expiresWith": "compat-removal-milestone",
        "milestone": COMPAT_REMOVAL_MILESTONE,
    },
    {
        "path": "dist/cursor/scripts/planning_store.py",
        "reason": "generated-compat-shim",
        "expiresWith": "compat-removal-milestone",
        "milestone": COMPAT_REMOVAL_MILESTONE,
    },
    {
        "path": "dist/claude-code/scripts/planning_store.py",
        "reason": "generated-compat-shim",
        "expiresWith": "compat-removal-milestone",
        "milestone": COMPAT_REMOVAL_MILESTONE,
    },
)


@dataclass(frozen=True)
class SizeFinding:
    path: str
    lineCount: int
    cap: int
    detail: str

    def to_dict(self) -> dict[str, object]:
        return {
            "path": self.path,
            "lineCount": self.lineCount,
            "cap": self.cap,
            "detail": self.detail,
        }


def _rel(root: Path, path: Path) -> str:
    try:
        return path.resolve().relative_to(root.resolve()).as_posix()
    except ValueError:
        return path.as_posix()


def is_distribution_path(rel: str) -> bool:
    return rel.startswith(DIST_PREFIXES)


def is_vendored_path(rel: str) -> bool:
    return VENDOR_PART in rel


def is_generated_file(path: Path) -> bool:
    try:
        head = path.read_text(encoding="utf-8")[:400]
    except OSError:
        return False
    return any(marker in head for marker in GENERATED_MARKERS)


def shim_exemption_for(rel: str) -> dict[str, str] | None:
    for row in SHIM_EXEMPTIONS:
        if row["path"] == rel:
            return dict(row)
    return None


def is_authored_package_module(rel: str) -> bool:
    return rel.startswith(AUTHORED_PACKAGE_PREFIX) and rel.endswith(".py")


def count_lines(path: Path) -> int:
    return len(path.read_text(encoding="utf-8").splitlines())


def lint_repo(root: Path) -> dict[str, object]:
    findings: list[SizeFinding] = []
    exemptions_applied: list[dict[str, str]] = []

    package_dir = root / AUTHORED_PACKAGE_PREFIX
    if package_dir.is_dir():
        for path in sorted(package_dir.rglob("*.py")):
            rel = _rel(root, path)
            if is_vendored_path(rel):
                continue
            line_count = count_lines(path)
            if line_count > MODULE_LINE_CAP:
                findings.append(
                    SizeFinding(
                        path=rel,
                        lineCount=line_count,
                        cap=MODULE_LINE_CAP,
                        detail="authored planning package module exceeds cap",
                    )
                )

    for row in SHIM_EXEMPTIONS:
        rel = row["path"]
        path = root / rel
        if not path.is_file():
            continue
        line_count = count_lines(path)
        exemptions_applied.append({**row, "lineCount": str(line_count), "capped": "false"})

    return {
        "verdict": "pass" if not findings else "fail",
        "cap": MODULE_LINE_CAP,
        "scopedTo": AUTHORED_PACKAGE_PREFIX,
        "exemptTrees": list(DIST_PREFIXES) + [VENDOR_PART],
        "shimExemptions": list(SHIM_EXEMPTIONS),
        "exemptionsApplied": exemptions_applied,
        "compatRemovalMilestone": COMPAT_REMOVAL_MILESTONE,
        "findings": [item.to_dict() for item in findings],
    }


def classify_path(root: Path, path: Path) -> dict[str, object]:
    rel = _rel(root, path)
    shim = shim_exemption_for(rel)
    return {
        "path": rel,
        "authoredPackageModule": is_authored_package_module(rel),
        "distribution": is_distribution_path(rel),
        "vendored": is_vendored_path(rel),
        "generated": is_generated_file(path) if path.is_file() else False,
        "shimExemption": shim,
        "subjectToCap": is_authored_package_module(rel)
        and not is_distribution_path(rel)
        and not is_vendored_path(rel),
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Lint authored planning package module sizes")
    parser.add_argument("--root", type=Path, default=Path.cwd())
    parser.add_argument("--check", action="store_true", help="Exit non-zero on findings")
    parser.add_argument("--classify", type=Path, help="Classify one path for cap/exemption policy")
    args = parser.parse_args(argv)
    root = args.root.resolve()

    if args.classify is not None:
        result = classify_path(root, args.classify)
        print(json.dumps(result, indent=2))
        return 0

    result = lint_repo(root)
    print(json.dumps(result, indent=2))
    if args.check and result.get("verdict") != "pass":
        return 20
    return 0


if __name__ == "__main__":
    run_module_main(main)
